/**
 * FIX-PARTS RESOLVER — turn a known issue's fix into a buyable part with verified links.
 *
 *   Workflow({ scriptPath: 'scripts/_wf-fixparts-resolver.js' })
 *
 * Third pipeline stage. Runs ONLY over already-published, already-verified issues, so it cannot
 * corrupt the research — worst case a part fails verification and the issue keeps its empty
 * fixParts. Targets chosen by scripts/_prep-fixparts-targets.js (recall-derived issues excluded:
 * their remedy is a free dealer repair and must never carry a buy link).
 *
 * REQUIRES WEBSEARCH. Unlike the recall waves, the evidence is not in hand — the whole job is
 * finding the real part and a real product page. Do not run this with an exhausted search budget:
 * agents will fall back to WebFetch, reach only fetchable hosts, and the failure mode is
 * *synthesised* links, which is exactly what must never ship.
 *
 * THE STANDARD (Devon's three pillars): accuracy, no-404 deep links, consistency.
 *  - Fitment-gated: a part number must match THIS make/model/year/engine. Cross-engine part
 *    numbers have silently produced wrong parts before (see the spec-DB audit).
 *  - Never synthesise a URL. Only product pages actually found in search results.
 *  - Better empty than wrong: an unresolved issue keeps empty fixParts and costs nothing.
 *
 * Output feeds scripts/_verify-buylinks.js (zero-AI liveness + soft-404 gate) BEFORE any DB write.
 */
export const meta = {
  name: 'fixparts-resolver',
  description: 'Resolve published issues to a buyable part: OEM PN, aftermarket cross-refs, price range, verified buy links',
  phases: [
    { title: 'Resolve' },
    { title: 'Verify' },
  ],
}

const TARGETS = [{"id":"mitsubishi-outlander-12v-auxiliary-battery-parasitic-drain-repeated-dead-battery","make":"Mitsubishi","model":"Outlander","years":[2022,2023,2024],"trims":["ES","SE","SEL","LE","Platinum Edition","PHEV"],"engines":["2.5L PR25DD I4","2.4L PHEV (4B12) hybrid"],"category":"electrical","severity":"medium","title":"12V Auxiliary Battery Parasitic Drain / Repeated Dead Battery","solution":"Diagnose parasitic draw with a multimeter (fuse-pull method) to isolate the offending circuit; check for infotainment/seat-module software updates at the dealer. Replace a degraded 12V battery (vented AGM type on PHEV) and verify DC-DC/alternator charging. Some owners fit a battery maintainer for vehicles parked for extended periods. Dealers have addressed specific VINs with module reprogramming.","description":"Fourth-generation Outlander and Outlander PHEV owners (2022+) report the 12V auxiliary battery repeatedly going flat, sometimes leaving the car dead in a day or two, even on nearly new vehicles and with the traction battery fully charged. Identified culprits on owner forums include the OEM infotainment/radio head unit failing to fully sleep, a driver's seat control module intermittently drawing current, a WiFi/telematics module, and a charging logic that tops up the 12V battery on a fixed daily timer rather than by voltage - so a low battery may never recover. Distinct from the high-voltage tr","estimatedCostLow":150,"estimatedCostHigh":600},{"id":"genesis-g90-air-suspension-failures-leaking-air-struts-bags-compressor-b","make":"Genesis","model":"G90","years":[2017,2018,2019,2020,2021,2022],"trims":[],"engines":["3.3L Twin-Turbo V6 (Lambda II)","5.0L V8 (Tau)"],"category":"suspension","severity":"high","title":"Air suspension failures — leaking air struts/bags, compressor burnout and rear sag","solution":"Diagnose the specific failed component: replace leaking air struts/bags, the compressor (often failing after it runs continuously trying to keep up with a leak), the air dryer, or a faulty height/leveling sensor. A dealer-only suspension ECU reboot/reset can resolve a rear that sags on startup when no leak is present. Fix leaks promptly to avoid killing the compressor.","description":"First-generation G90s use an electronically controlled air suspension that is a recurring high-cost failure point. Owners report pinhole leaks in the air struts/bags, failed leveling (height) sensors, exploded air dryers and burnt-out compressors, producing a saggy or uneven stance, knocking noises over bumps and a harsh ride. Repeated compressor/strut failures can run into the thousands of dollars. Genesis abandoned this air-suspension design on the redesigned G90.","estimatedCostLow":800,"estimatedCostHigh":4000},{"id":"genesis-g90-coolant-leaks-from-water-pump-thermostat-housing","make":"Genesis","model":"G90","years":[2017,2018,2019,2020,2021,2022],"trims":[],"engines":["3.3L Twin-Turbo V6 (Lambda II)","5.0L V8 (Tau)"],"category":"cooling","severity":"medium","title":"Coolant leaks from water pump and thermostat housing","solution":"Pressure-test the cooling system to pinpoint the source. Replace the water pump (G90 water pump PN 25100-3F300) and/or thermostat housing with new gaskets; clean and flatten mating surfaces and torque bolts in sequence to spec to avoid a repeat leak. Refill with the correct Hyundai/Genesis long-life coolant and bleed air.","description":"Coolant weeping/leaks are frequently reported and seen by technicians on first-gen G90s — commonly from the water pump and thermostat housing on the 3.3T, plus O-ring/gasket seepage on the 5.0. Left unaddressed, slow coolant loss risks overheating and cylinder-head damage on the Lambda/Tau V6/V8 family.","estimatedCostLow":350,"estimatedCostHigh":900},{"id":"genesis-g90-repeated-12v-battery-drain-dead-battery-from-head-unit-modul","make":"Genesis","model":"G90","years":[2017,2018,2019,2020,2021,2022,2023],"trims":[],"engines":["3.3L Twin-Turbo V6 (Lambda II)","5.0L V8 (Tau)","3.5L Twin-Turbo V6 (Smartstream)"],"category":"electrical","severity":"medium","title":"Repeated 12V battery drain / dead battery from head unit and modules drawing power when parked","solution":"Measure key-off parasitic draw with a clamp/multimeter (target under ~50 mA); pull fuses to isolate the offending circuit. Where the head unit is the source, dealers have replaced it under warranty. Replace a degraded battery, keep the fob away from the vehicle when parked, and use a maintainer for cars that sit.","description":"Owners across model years report the 12V battery going flat after the car sits a few days. A common documented culprit is the radio/head unit continuing to draw current after shutdown, along with other parasitic draws that exceed the normal <50 mA key-off current. Leaving the key fob near the car can compound it. Frequent deep discharges shorten battery life and can leave the car unable to start.","estimatedCostLow":250,"estimatedCostHigh":1500},{"id":"ram-1500-ecodiesel-fuel-pump-2014","make":"RAM","model":"1500","years":[2014,2015,2016,2017,2018,2019,2020,2021,2022],"trims":["Big Horn","Laramie","Laramie Longhorn","Limited","Limited Longhorn","Lone Star","Rebel"],"engines":["3.0L EcoDiesel"],"category":"fuel","severity":"high","title":"EcoDiesel Fuel Pump Failure / Stalling","solution":"Check the VIN for Z46 / 22V406 and Z96 / 22V767. Have the dealer replace the high-pressure fuel pump and inspect or replace additional fuel-system components as necessary, free of charge. If the engine stalls or loses power, use hazards, steer and brake to a safe location and arrange service. Do not buy a high-pressure pump, injector, rail or fuel-system kit from this page; campaign eligibility, contamination extent, completed remedy, current part number and VIN fitment must be established first.","description":"NHTSA 22V406 / FCA Z46 covers affected 2014-2019 RAM 1500 trucks with the 3.0L diesel, while 22V767 / FCA Z96 covers affected 2020-2022 RAM 1500 trucks with that engine. High-pressure fuel-pump failure can introduce debris or cause fuel starvation and an unexpected loss of drive power. Together the campaigns support the indexed model-year span, but only VIN-selected vehicles are included and no owner-frequency count is established.","estimatedCostLow":null,"estimatedCostHigh":null},{"id":"ram-1500-etorque-mild-hybrid-2019","make":"RAM","model":"1500","years":[2019,2020,2021,2022,2023,2024,2025],"trims":[],"engines":[],"category":"electrical","severity":"medium","title":"eTorque Mild Hybrid System Failure","solution":"Diagnose with a Mopar wiTECH scan tool to identify if the 48V battery, BDM, or control module is at fault. Check TSB 08-074-20 REV.A for motor generator noise. If the 48V battery is degraded (below 42V resting), replace the battery pack under the rear seat ($800-1,500). If the BDM is failed, replace the unit and serpentine belt ($1,200-2,000). Software reflash may resolve intermittent issues. The eTorque system is covered under the powertrain warranty (5yr/60k miles).","description":"The 2019+ RAM 1500 with eTorque mild hybrid system (standard on V6, optional on V8) experiences failures of the 48-volt battery pack, belt-driven motor generator (BDM), and eTorque control module. Symptoms include rough idle, stalling at stops, auto start-stop not working, and \"Service eTorque System\" warning messages. The 48V lithium-ion battery pack located under the rear seat deteriorates over time, especially in hot climates. TSB 08-074-20 REV.A addresses eTorque motor generator unit noise and vibration. Replacement of the 48V battery pack costs $800-1,500 and the BDM unit runs $1,200-2,00","estimatedCostLow":800,"estimatedCostHigh":2000},{"id":"chevrolet-traverse-loss-power-steering-assist-from-hydraulic-power-steering-pum","make":"Chevrolet","model":"Traverse","years":[2009,2010,2011],"trims":["LS","LT","LTZ"],"engines":["3.6L V6 (LLT)","3.6L V6 (LY7)"],"category":"steering","severity":"high","title":"Loss of Power Steering Assist from Hydraulic Power Steering Pump Wear","solution":"Diagnose the hydraulic power steering system for pressure loss; the fix is typically replacement of the power steering pump (and repair of any leaking high-pressure line or rack). Check eligibility for GM Special Coverage #14329 (10yr/150k on 2009-2011) before paying out of pocket.","description":"First-generation Traverse owners report an intermittent or sudden drop in power-steering assist, with heavy/hard steering especially at low speed and parking, often preceded by a whine from the pump. This is a HYDRAULIC power steering system (engine-driven pump), and the failure is internal flow-control-valve/seal wear in the pump that causes a loss of hydraulic pressure; the vehicle can revert to a manual-effort state. GM issued Special Coverage Adjustment #14329 for this pump-wear condition on 2009-2011 Traverse (and 2008-2011 Enclave, 2007-2011 Acadia, 2007-2010 Saturn Outlook), extending p","estimatedCostLow":500,"estimatedCostHigh":1500},{"id":"chevrolet-traverse-timing-chain-stretch-2009","make":"Chevrolet","model":"Traverse","years":[2009,2010,2011,2012,2013,2014,2015,2016,2017],"trims":[],"engines":["LLT","LFX"],"category":"engine","severity":"high","title":"Timing Chain Stretch and Failure (3.6L V6 LLT/LFX)","solution":"Replace all three timing chains, tensioners, guides, and VVT actuator solenoids. This is a major repair requiring 10-15 hours of labor because the engine must be partially removed or the front cover fully disassembled. Parts cost $300-$600 for a complete timing kit; labor runs $1,200-$2,500. Total cost: $1,500-$3,500. GM extended warranty coverage to 10 years/120,000 miles on some model years (Special Coverage 14311). Always replace all three chains together — replacing just one is false economy as the others will fail soon after.","description":"The 3.6L V6 (LLT and LFX variants) in the first-generation Traverse is notorious for premature timing chain stretch. The engine uses three timing chains — one primary and two secondary chains driving the variable valve timing actuators. The chains stretch beyond the tensioner capacity, causing the engine timing to slip. Symptoms progress from a rattle on cold start to a check engine light with camshaft correlation codes. If ignored, the stretched chains can skip teeth, causing catastrophic engine damage. The issue typically manifests between 80,000-120,000 miles.","estimatedCostLow":1500,"estimatedCostHigh":3500},{"id":"chevrolet-traverse-hydraulic-steering-gear-internal-seal-leak-fluid-loss-groani","make":"Chevrolet","model":"Traverse","years":[2009,2010,2011,2012],"trims":["LS","LT","LTZ"],"engines":[],"category":"steering","severity":"high","title":"Hydraulic Steering Gear (Rack and Pinion) Internal Seal Leak — Fluid Loss and Groaning Assist","solution":"Confirm the source of the leak before buying parts — clean the area, dye the fluid, and drive it, because a leaking pump, a leaking high-pressure hose, and a leaking gear all present as the same low-fluid groan. If the gear is the source, the only durable repair is replacement of the rack and pinion assembly (reseal kits are not serviceable on this unit); match the NV7 variable-assist part if the vehicle is so equipped, then flush the system and bleed it fully. Check whether the VIN falls under GM's power steering special coverage extension to 100,000 miles before paying out of pocket. Replace the pump at the same time only if it is also noisy or leaking.","description":"Separate from the well-known power steering pump wear, the first-generation Traverse's hydraulic rack and pinion assembly itself leaks. The internal rack seals and the upper input shaft seal weep power steering fluid, often visible as fluid running down the rack boots or dripping from the crossmember. Because the leak starves the pump, many owners replace the pump first and are back at the dealer weeks later. Traverse Forum threads document owners with as little as 23,000 miles being quoted $1,500-$1,750 for a steering gear, and GM ran a special service coverage extension to 100,000 miles on 2","estimatedCostLow":900,"estimatedCostHigh":1950},{"id":"chevrolet-traverse-ac-compressor-2009","make":"Chevrolet","model":"Traverse","years":[2009,2010,2011,2012,2013,2014,2015,2016,2017],"trims":[],"engines":[],"category":"other","severity":"medium","title":"AC Compressor Premature Failure","solution":"Confirm the failure by checking static and running refrigerant pressures, verifying compressor clutch command/power and ground, and inspecting for noise, seizure, or metal contamination in the oil and lines. If the compressor has failed internally, replace the compressor, receiver/drier or condenser assembly (the drier is integrated on many GM systems), expansion valve/orifice components as applicable, thoroughly flush any reusable lines and evaporator, evacuate the system, and recharge with the exact specified refrigerant and PAG oil; also inspect cooling fan operation and high-side pressures so an overpressure condition does not destroy the replacement unit. If debris is present, a simple compressor swap often leads to repeat failure, so a full system cleanout is the correct repair. Typical cost is about $1,200-$2,500 for a complete repair depending on how many contaminated components must be replaced.","description":"The Traverse has one of the highest rates of AC compressor failure among midsize SUVs. Compressors seize or lose capacity often before 70,000 miles. When the compressor fails, it can send metal debris through the entire AC system, requiring replacement of the condenser, expansion valve, and system flush. Some owners report repeat failures within 8 months of repair.","estimatedCostLow":800,"estimatedCostHigh":2000},{"id":"chevrolet-traverse-ac-evaporator-leak-2009","make":"Chevrolet","model":"Traverse","years":[2009,2010,2011,2012,2013,2014,2015,2016,2017],"trims":[],"engines":[],"category":"cooling","severity":"medium","title":"A/C Evaporator Core Leak","solution":"The evaporator core must be replaced, which requires removing the entire dashboard assembly to access the HVAC housing — 8-12 hours of labor ($800-$1,500). The evaporator core itself costs $100-$300. Also replace the expansion valve and receiver/drier while the system is apart ($50-$100 additional). Total repair: $1,200-$2,500. As a temporary fix, a refrigerant recharge with UV dye ($100-$200) will restore cooling for weeks to months, but the leak will return. Always check for evaporator leaks before spending money on other A/C diagnostics.","description":"The first-generation Traverse (2009-2017) develops A/C evaporator leaks that cause loss of refrigerant and warm air from the vents. The evaporator core, located inside the dashboard HVAC housing, corrodes internally due to moisture and acid buildup from the refrigerant-oil mixture. The leak is slow enough that the A/C may work fine early in summer but gradually loses cooling as refrigerant escapes over weeks. The evaporator is extremely labor-intensive to access, making this one of the most expensive A/C repairs.","estimatedCostLow":100,"estimatedCostHigh":2500},{"id":"chevrolet-traverse-evap-purge-valve-failure-causing-rough-idle-stalling-hard-st","make":"Chevrolet","model":"Traverse","years":[2019],"trims":[],"engines":[],"category":"emissions","severity":"medium","title":"EVAP Purge Valve Failure Causing Rough Idle, Stalling and Hard Starts (P0496) — GM Special Coverage N232395300","solution":"Replace the failed evaporative emission purge/solenoid valve (free under GM Special Coverage N232395300 on eligible 2019 3.6L units); clear P0496 and verify EVAP system seal. Check for related EVAP codes (P0442, P0455) that can accompany the failure.","description":"On the 3.6L V6 (RPO LFY) Traverse, the evaporative emissions purge valve can fail to fully close, allowing fuel vapor to flood the intake. This causes a P0496 (EVAP high purge flow) code with rough running, hesitation, or stalling at idle, and hard starting after refueling. GM acknowledged the condition and issued Special Coverage N232395300 (15 years / 150,000 miles) to replace the purge valve at no charge on affected 2019 Traverse units.","estimatedCostLow":null,"estimatedCostHigh":null},{"id":"chevrolet-traverse-hvac-blend-door-actuator-failure-warm-air-one-side-inconsist","make":"Chevrolet","model":"Traverse","years":[2018,2019,2020,2021,2022,2023],"trims":[],"engines":[],"category":"hvac","severity":"medium","title":"HVAC Blend Door Actuator Failure — Warm Air on One Side / Inconsistent Dual-Zone Temps","solution":"Diagnose and replace the failed HVAC blend door actuator(s) for the affected zone, then recalibrate the climate system. A clicking/knocking sound from behind the dash typically indicates actuator gear failure.","description":"The dual-zone climate system on the Traverse commonly suffers blend door actuator failures, where one side (often the passenger side or rear) blows warm air while the other blows cold regardless of temperature setting. The plastic gears inside the actuator strip or stick, often producing a clicking/knocking sound from behind the dash; this is a recurring complaint shared across GM models with split climate control.","estimatedCostLow":null,"estimatedCostHigh":null},{"id":"chevrolet-traverse-water-pump-shaft-seal-coolant-leak","make":"Chevrolet","model":"Traverse","years":[2009,2010,2011,2012,2013,2014,2015,2016,2017],"trims":["LS","LT","LTZ"],"engines":["3.6L V6 (LLT)","3.6L V6 (LY7)"],"category":"cooling","severity":"medium","title":"Water Pump Shaft Seal Coolant Leak (3.6L V6)","solution":"Replace the water pump (and thermostat/gaskets while accessed), pressure-test the cooling system, and refill with DEX-COOL. Keeping coolant topped to spec extends seal life. #13079 (a coolant-level check/top-off program, not a free pump replacement) applied to eligible 2009-2013 cars until April 30, 2015; otherwise owner-pay.","description":"The engine-driven water pump on the 3.6L V6 develops a leak at the shaft seal, weeping coolant from the pump 'weep hole' at the front/side of the engine. GM acknowledged the condition with Customer Satisfaction Program #13079 covering 2009-2013 Traverse (and Lambda-platform siblings Enclave/Acadia/Outlook) with the HFV6 engine (LY7, LLT), noting that operating with a low coolant level shortens shaft-seal life. Water-pump leaks are widely reported across first-gen years through 2017. Left unaddressed the pump can lose enough coolant to cause overheating.","estimatedCostLow":700,"estimatedCostHigh":1700},{"id":"chevrolet-traverse-camshaft-position-actuator-solenoid-faults-3-6l-lfy-over-adv","make":"Chevrolet","model":"Traverse","years":[2018,2019,2020],"trims":[],"engines":["3.6L V6 LFY"],"category":"engine","severity":"medium","title":"Camshaft Position Actuator Solenoid Faults on the 3.6L LFY — Over-Advanced Cam Timing and Rough Running","solution":"Start with a known-good oil and filter service using dexos1 5W-30 full synthetic — degraded or overfilled oil alone will set these codes on this engine. Then check with a dealer whether ECM calibration bulletin N192266190 is open for the VIN; the reprogram resolves a meaningful share of cases at no parts cost. If codes persist after the reflash, test the cam actuator solenoids for correct resistance and replace the affected solenoid(s) and screens; heavily varnished engines may need the phasers themselves. Only after solenoid and oiling causes are excluded should chain stretch be suspected — and verify it with an actual cam/crank correlation measurement, not an assumption.","description":"The second-generation 3.6L LFY runs four cam phasers fed by oil-control solenoids. On early C1XX Traverse builds the solenoids stick or screen-clog with casting/machining debris and varnish, and the ECM calibration was itself part of the problem. The result is a set of correlated cam timing codes — commonly P0011 with P0014, P0021 and P0024 appearing together — plus a rough idle, a rattle on start-up as the phasers fail to lock, and reduced power. GM addressed the calibration side with bulletin N192266190 (ECM reprogram). This is distinct from the LLT/LFX timing chain stretch problem: the chai","estimatedCostLow":150,"estimatedCostHigh":900},{"id":"chevrolet-traverse-front-wheel-bearing-hub-assembly-failure-highway-growl-abs-s","make":"Chevrolet","model":"Traverse","years":[2009,2010,2011,2012,2013,2014,2015,2016,2017,2018,2019,2020,2021,2022,2023],"trims":[],"engines":[],"category":"suspension","severity":"medium","title":"Front Wheel Bearing and Hub Assembly Failure — Highway Growl with ABS and StabiliTrak Warnings","solution":"Diagnose by road-testing with weight transfer: swerve gently side to side at 40-50 mph and note whether the noise increases when the suspect corner is loaded. Confirm with a dial indicator for lateral play at the hub flange. The repair is replacement of the complete hub/bearing assembly (the bearing is not separately serviceable), including a new axle nut torqued to spec. Seat the wheel speed sensor connector carefully — improperly seated sensors after a hub job are a well-documented cause of ABS lights that were not there before. Replace in axle pairs if both sides have comparable mileage.","description":"The Traverse is a heavy three-row crossover on a front-drive-biased platform, and the front wheel bearing/hub assemblies are a recurring wear failure across both the Lambda and C1XX generations. The bearing develops a speed-dependent hum or growl that changes pitch when the vehicle is loaded into a turn. Because the wheel speed sensor is integrated into the hub unit, a failing bearing frequently damages or de-tunes the sensor, so the first symptom many owners see is an ABS and StabiliTrak warning light rather than a noise. There is no recall for this on any model year — it is a maintenance-gra","estimatedCostLow":300,"estimatedCostHigh":800},{"id":"chevrolet-traverse-liftgate-strut-failure-2009","make":"Chevrolet","model":"Traverse","years":[2009,2010,2011,2012,2013,2014,2015,2016,2017,2018,2019,2020,2021,2022,2023,2024,2025],"trims":[],"engines":[],"category":"body","severity":"low","title":"Power Liftgate Strut Failure","solution":"Replace both liftgate struts as a pair ($50-$120 for a pair of gas struts). This is a simple DIY repair — the struts have ball-socket ends that pop off with a small pry tool (15-minute job). For power liftgate models, if the electric motor has failed, the motor assembly costs $200-$500 and requires 1-2 hours of labor to replace. StrongArm and Sachs/Stabilus are quality aftermarket strut brands. Always replace both struts at the same time — they wear at the same rate.","description":"The Traverse power liftgate struts lose gas pressure over time, causing the liftgate to drop slowly when opened or slam shut unexpectedly. On models with power liftgate, the electric motor can also fail, leaving the liftgate inoperative via the button. The struts typically fail between 5-8 years, with cold weather accelerating the failure as the gas charge loses pressure faster at low temperatures. A dropping liftgate is a safety concern, especially when loading cargo or with children nearby.","estimatedCostLow":50,"estimatedCostHigh":600},{"id":"lincoln-aviator-12v-battery-drain-repeated-dead-battery","make":"Lincoln","model":"Aviator","years":[2020,2021,2022],"trims":[],"engines":[],"category":"electrical","severity":"medium","title":"12-Volt Battery Drain from Third-Party App Modem Activity","solution":"Identify and uninstall any non-Ford/Lincoln app that accesses the vehicle, then fully charge and test the 12-volt battery and monitor key-off draw and battery state of charge. If symptoms remain, follow normal Ford battery, battery-monitoring-sensor, charging-system, modem, and module network-sleep diagnostics. A Deep Sleep notification by itself is not a failed module; if state of charge does not change after charging or a BMS reset, continue the battery/BMS diagnostic path. Do not replace a latch, TCU, battery, or other module without a failed test, and do not present a maintainer as the repair for an unresolved drain.","description":"Ford SSM 50804 says some 2020-2022 Aviators with an activated modem may have 12-volt battery-drain symptoms when unaffiliated third-party phone applications repeatedly request vehicle commands such as lock, unlock, remote start, or location. Those calls can keep the vehicle network active. This is one documented cause, not proof that every dead battery is a TCU, latch, battery, or module failure. Ford separately explains that a Deep Sleep notification can be normal after 14 days, low voltage, state of charge below 50 percent, or a TCU update.","estimatedCostLow":null,"estimatedCostHigh":null},{"id":"lincoln-aviator-total-loss-audio-from-rear-water-leak-damaging-audio-control","make":"Lincoln","model":"Aviator","years":[2020,2021,2022,2023],"trims":[],"engines":[],"category":"electrical","severity":"medium","title":"Lack of Audio with Rear-Liftgate or Spare-Tire Water Leak - TSB 23-2181","solution":"Confirm both the audio symptom and rear water evidence, then follow the Aviator inspection sequence in TSB 23-2181. Correct only the leak path found: reseat or replace the specified grommet/strut when required, seat seals and connectors, repair plugs or washer-hose routing, and verify the BLIS module and harness grommets. If right-side water is present, follow the bulletin's ACM replacement step and use the VIN-specific parts catalog application. Dry and inspect affected connectors and trim as directed. Coverage depends on the vehicle's applicable warranty or service plan; this record has no commerce link.","description":"Some 2020-2023 Aviators may exhibit lack of audio after rainfall or a car wash together with water in the rear-liftgate area or spare-tire area. Ford TSB 23-2181 directs Aviator-specific inspection of the power-liftgate grommet, margin seal and pushpins, electrical-wiring grommet, rear washer hose, body-hole plugs, BLIS-module seating, and BLIS harness grommets. The bulletin calls for ACM replacement when right-side water is present; it does not establish water damage as the cause of every audio outage.","estimatedCostLow":null,"estimatedCostHigh":null},{"id":"nissan-frontier-rear-diff-bushing-2005","make":"Nissan","model":"Frontier","years":[2005,2006,2007,2008,2009,2010,2011,2012,2013,2014,2015,2016,2017,2018,2019,2020,2021],"trims":[],"engines":[],"category":"drivetrain","severity":"low","title":"Rear Differential Bushing Clunk","solution":"Replace the rear differential mount bushings with polyurethane or upgraded rubber bushings. DIY cost: $30-80 for bushings. Shop labor: $150-300. Some owners install solid differential mounts or polyurethane mounts for a more permanent fix, though these may increase NVH. The upper and lower diff mounts should both be replaced at the same time.","description":"The D40 Frontier develops a clunk from the rear end during acceleration and deceleration transitions, caused by worn rear differential mount bushings. The rubber bushings deteriorate over time, allowing the differential to shift and create a noticeable \"clunk\" when transitioning between acceleration and coast. This is one of the most commonly reported issues on Frontier forums and typically starts around 40,000-60,000 miles.","estimatedCostLow":30,"estimatedCostHigh":400},{"id":"gmc-terrain-1-5t-pcv-oil-leak-2018","make":"GMC","model":"Terrain","years":[2018,2019,2020,2021,2022,2023,2024,2025],"trims":[],"engines":["1.5L Turbo LFV","1.5L Turbo LYX"],"category":"engine","severity":"high","title":"1.5L Turbo PCV System Failure and Coolant/Oil Intrusion","solution":"Replace valve cover assembly with updated GM part (GM 12690058) which includes the revised PCV diaphragm. Clean intercooler and intake manifold of oil contamination. Check for coolant consumption alongside oil intrusion. Inspect air-to-water intercooler for coolant contamination — replacement if contaminated (GM 84446987).","description":"The 2018+ Terrain with the 1.5L turbocharged engine (LFV/LYX) experiences PCV (Positive Crankcase Ventilation) diaphragm failure inside the valve cover. The integrated PCV diaphragm tears, causing excessive crankcase pressure that forces oil into the intake manifold and intercooler. Symptoms include oily residue around the air intake and intercooler outlet pipe. In severe cases, excessive crankcase pressure also causes coolant intrusion into the combustion chamber. GM issued TSB PIT5697 for this issue. This is the same problem affecting the Chevrolet Equinox 1.5T of the same era.","estimatedCostLow":400,"estimatedCostHigh":2800},{"id":"mazda-cx60-12v-battery-drain-warning","make":"Mazda","model":"CX-60","years":[2022,2023],"trims":[],"engines":[],"category":"electrical","severity":"medium","title":"2022-Early 2023 CX-60 12V Battery Drain from BCM Power-Saving Software","solution":"Check the VIN against Mazda campaigns for the vehicle's market. For an affected vehicle, Mazda's remedy is BCM software reprogramming, not a trickle charger or blindly replacing the battery. If the VIN is not covered or the drain remains, fully charge the 12V battery, test its condition and charging strategy, measure key-off current only after all modules have had time to sleep, and isolate the circuit that remains awake. Replace the 12V battery only if it fails the appropriate test, using the exact installed specification for that powertrain and completing any required battery initialisation. Repeatedly discharged batteries should be tested because deep discharge can cause permanent capacity loss.","description":"Mazda's Japanese April 2023 service campaign covers specified early CX-60 chassis. On vehicles equipped with Driver Personalisation, rapidly repeating push-button-start operation can expose an incorrect body-control-module program: after power-off, the vehicle may fail to enter its low-power state and continued current draw can discharge the 12V battery. This is one verified cause for the early-production campaign population, not proof that every low-battery warning or flat CX-60 battery has the same cause.","estimatedCostLow":null,"estimatedCostHigh":null},{"id":"gmc-terrain-sunroof-drain-hose-clogging-disconnection-water-cabin-floor","make":"GMC","model":"Terrain","years":[2010,2011,2012,2013,2014,2015,2016,2017],"trims":[],"engines":[],"category":"body","severity":"medium","title":"Sunroof Drain Hose Clogging and Disconnection - Water on the Cabin Floor and Headliner Staining","solution":"Water-test each corner, clear the drains with low pressure or safe flexible line, then reconnect or replace only the failed hose/coupler. The updated hose and access differ by roof module and generation; generic wire or a universal hose is not approved.","description":"Sunroof-equipped first-generation Terrains use a drain trough around the glass panel with four hoses routed down the A-pillars and out through the rear body-side extensions. The original-design hoses are small in diameter and prone to clogging with debris and factory sealant residue; owners commonly find three of four drains blocked. The hoses also shrink with age and pull off the sunroof module fitting. Once a drain backs up, water overflows the trough into the headliner and runs down onto the front or rear carpet. GM issued a service bulletin covering wet floors and interior water leaks on 2","estimatedCostLow":100,"estimatedCostHigh":800},{"id":"mercedes-benz-glc-active-brake-assist-360-degree-camera-false-activations","make":"Mercedes-Benz","model":"GLC","years":[2017,2018,2019,2020,2021,2022,2023,2024],"trims":[],"engines":[],"category":"safety","severity":"high","title":"Active Brake Assist and 360-Degree Camera False Activations (Phantom Braking)","solution":"Read radar/camera event memory, install the current control-unit software and check sensor alignment/calibration, especially after glass or front-end work. No sensor or camera is approved until a specific failed component is established.","description":"GLC owners report the driver-assistance suite reacting to obstacles that are not there. The \"checking surroundings\" screen pops up several times a week with sections of the car outlined in red and nothing nearby, and — more seriously — Active Brake Assist has applied the brakes with no vehicle or object ahead. Owners on the Mercedes forums describe the system cutting the accelerator because it believes an obstacle is present, and multiple owners across the GLC and its C-Class platform siblings report the same event, encouraging one another to file NHTSA complaints. Mercedes has attributed comp","estimatedCostLow":0,"estimatedCostHigh":1500},{"id":"alfa-romeo-stelvio-parasitic-battery-drain-from-modules-failing-to-sleep-repeat","make":"Alfa Romeo","model":"Stelvio","years":[2018,2019,2020,2021,2022,2023,2024,2025],"trims":[],"engines":[],"category":"electrical","severity":"medium","title":"Parasitic Battery Drain From Modules Failing to Sleep, Repeat Dead Batteries","solution":"Do not simply replace the battery - measure first. With the car fully asleep (allow 30-60 minutes after locking, doors closed, fobs moved well away from the vehicle), measure current draw at the negative terminal; sustained draw above ~50 mA indicates a fault. Then pull fuses systematically to isolate the circuit. Where the BCM is the source, Stellantis TSBs covering BCM-related battery drain apply and the fix is a software update or module replacement - budget roughly $600-$1,200 for BCM replacement and programming. Also verify the battery itself and the intelligent battery sensor, and register any new battery to the vehicle. Owners who store the car should use a maintainer and keep fobs at a distance.","description":"One of the most-discussed problems in the Stelvio owner community and one of the most commonly misdiagnosed. A module that fails to enter sleep mode - most often the body control module, per forum consensus - keeps the CAN bus awake and holds current draw far above spec. Owners report a dead or near-dead battery after only three to four days of the car sitting. The tell is that draw stays well above the roughly 20 mA a sleeping Stelvio should pull; anything sustained above about 50 mA is a genuine parasitic drain. Repeated deep discharge then damages the battery itself, producing a 'death spir","estimatedCostLow":300,"estimatedCostHigh":1200},{"id":"alfa-romeo-stelvio-water-pump-housing-gasket-leak-causing-slow-coolant-loss","make":"Alfa Romeo","model":"Stelvio","years":[2018,2019,2020,2021,2022,2023,2024],"trims":[],"engines":["2.0L I4 turbo GME T4"],"category":"cooling","severity":"medium","title":"Water Pump Housing and Gasket Leak Causing Slow Coolant Loss","solution":"Replace the water pump as an assembly with a new housing gasket; patching a leaking housing is not viable. Expect roughly $600-$1,200 at an independent shop and more at a dealer, driven by access. Pressure-test the cooling system first to distinguish the pump from the turbo coolant feed pipe collar, the thermostat housing, and the plastic bleeder screws, all of which leak on this platform and all of which present as the same slow loss. Do not top off and ignore it - the 2.0L turbo is intolerant of running low and overheating escalates to head gasket territory.","description":"A recurring cooling-system failure on the 2.0L cars, separate from the Quadrifoglio hose recall. The water pump leaks from the housing itself or from the housing-to-block gasket, producing a slow drip rather than a dramatic failure. Because the leak is small and the coolant on this platform dries to a pinkish or orange crust, owners often chase a phantom low-coolant light for months. Forum reports include a 2018 car with a failed pump at about 41,000 km (roughly 25,000 miles), so this is not purely an age-and-mileage wear item. A related and frequently confused leak point on the same engine is","estimatedCostLow":600,"estimatedCostHigh":1200},{"id":"ford-f150-vacuum-pump-2015","make":"Ford","model":"F-150","years":[2015,2016,2017,2018,2019,2020],"trims":[],"engines":["2.7L EcoBoost","3.5L EcoBoost","EcoBoost"],"category":"brakes","severity":"high","title":"Brake Vacuum Pump Failure (EcoBoost)","solution":"Replace vacuum pump. This is a safety-critical repair - do not drive with failed pump. Check for diagnostic codes related to brake booster. Inspect vacuum lines for leaks as well.","description":"The vacuum pump that provides brake assist on EcoBoost F-150s can fail, resulting in a hard brake pedal and reduced braking assist. Since turbo engines don't produce intake vacuum like naturally aspirated engines, they rely on this pump.","estimatedCostLow":300,"estimatedCostHigh":800},{"id":"ford-f-150-3-5l-ecoboost-primary-timing-chain-stretch-p0016-cold-start","make":"Ford","model":"F-150","years":[2011,2012,2013,2014,2015,2016,2017],"trims":[],"engines":["3.5L EcoBoost V6 (Gen 1)"],"category":"engine","severity":"high","title":"3.5L EcoBoost Primary Timing Chain Stretch — P0016 and Cold-Start Rattle","solution":"Confirm with a scan tool (P0016 cam/crank correlation) and verify chain stretch versus a sticking VCT solenoid before tear-down. The fix is a full timing-chain overhaul — primary and secondary chains, guides, tensioners, phasers, and VCT solenoids. Use the updated Ford parts; many shops replace the cam-position sensors and water pump while in there. Stay on the 5W-30 spec, change oil every 5,000 miles, and avoid extended intervals. Major job: $1,800-$3,000+ with labor. Catching it at the first cold-start rattle prevents engine destruction.","description":"Distinct from the cam-phaser cold-start rattle, the first-generation (2011-2016) 3.5L EcoBoost suffers genuine primary timing-chain wear ('stretch') because of its long chain routing and the high loads of a twin-turbo direct-injection V6. As the chain pins and rollers wear, the cam-to-crank relationship drifts and the PCM logs P0016 (and related correlation codes). The first symptom is usually a brief metallic rattle on cold start that worsens over time. Wear typically appears around 100,000-150,000 miles, often accelerated by extended oil-change intervals. Left unrepaired, the chain can skip ","estimatedCostLow":1800,"estimatedCostHigh":3200},{"id":"ford-f150-oil-pan-leak-2015","make":"Ford","model":"F-150","years":[2015,2016,2017,2018,2019,2020],"trims":[],"engines":["3.5L EcoBoost","2.7L EcoBoost","EcoBoost 3.5"],"category":"engine","severity":"medium","title":"EcoBoost Oil Pan Leak","solution":"Replace oil pan gasket. The repair is labor-intensive as the subframe often needs to be lowered for access. Use OEM gasket for best results. Clean oil pan and block mating surfaces thoroughly.","description":"The EcoBoost engines can develop oil leaks from the oil pan gasket. The leak often appears at the rear of the oil pan and can drip onto exhaust components, causing a burning oil smell. This is common on trucks with higher mileage.","estimatedCostLow":400,"estimatedCostHigh":1200},{"id":"ford-f-150-6r80-6-speed-automatic-harsh-1-2-upshift-erratic-shifting-le","make":"Ford","model":"F-150","years":[2009,2010,2011,2012,2013,2014,2015,2016,2017],"trims":[],"engines":["3.5L EcoBoost V6","5.0L Coyote V8","3.7L Ti-VCT V6","6.2L V8"],"category":"transmission","severity":"medium","title":"6R80 6-Speed Automatic Harsh 1-2 Upshift / Erratic Shifting and Lead-Frame Solenoid Body Failure","solution":"Start with a full fluid-and-filter service using Mercon LV (the 'lifetime fill' should still be serviced ~every 60k, sooner with towing). Have the dealer flash the PCM/TCM to the latest calibration — Ford released shift-quality calibration updates that fix many harsh/delayed-engagement complaints as the first repair. Persistent harsh shifting or specific solenoid codes call for a solenoid body / lead-frame replacement (Ford solenoid body assembly, commonly cross-referenced as Sonnax/aftermarket units). A TCM adaptive (keep-alive) reset and relearn is required after repairs. Fluid service $200-$400; solenoid body $600-$1,200 installed; valve-body/rebuild far more.","description":"The 6R80 six-speed automatic (2009-2017 F-150) is generally durable but is widely reported for a harsh, banging 1-2 upshift and erratic/flaring shifts, with thousands of NHTSA complaints. The internal solenoid body 'lead frame' (the mechatronic wiring carrier) can crack or develop failing solenoid calibration, and the adapt strategy struggles to relearn after service. The classic symptom is a 1-2 shift so abrupt owners describe it as a jolt that could 'knock a cup of coffee out of your hand.' Towing, worn fluid, and never-serviced 'lifetime' fluid accelerate the problem. It is a top transmissi","estimatedCostLow":250,"estimatedCostHigh":1500},{"id":"ford-f-150-coolant-degas-overflow-bottle-cracks-quick-connect-fitting-l","make":"Ford","model":"F-150","years":[2015,2016,2017,2018,2019,2020,2021,2022,2023],"trims":[],"engines":["2.7L EcoBoost V6","3.5L EcoBoost V6","5.0L Ti-VCT V8"],"category":"cooling","severity":"medium","title":"Coolant Degas / Overflow Bottle Cracks and Quick-Connect Fitting Leaks","solution":"Pressure-test the cooling system to reveal the weep. Replace the degas bottle and any cracked plastic tee/Y quick-connect fittings as an assembly — a new hose/fitting will not seal reliably on an old bottle neck. Replace shrunken O-rings on quick-connects. Refill with the correct Ford orange/yellow spec coolant and burp the system.","description":"The plastic pressurized coolant degas (overflow/expansion) bottle and the plastic quick-connect tees/Y-fittings that route coolant between the block, radiator, and bottle develop hairline cracks and seep, especially at seams and hose necks and in cold weather where the square-cut O-rings on the quick-connects shrink. Owners chase a slow coolant loss and sweet smell that is hard to pinpoint because the crack only weeps under pressure or when cold. If ignored it can lead to low-coolant overheating.","estimatedCostLow":150,"estimatedCostHigh":450},{"id":"ford-f-150-sync-2-sync-3-apim-failure-black-screen-freezing-reboot-loop","make":"Ford","model":"F-150","years":[2013,2014,2015,2016,2017,2018,2019,2020],"trims":[],"engines":["All (infotainment, engine-independent)"],"category":"electrical","severity":"medium","title":"SYNC 2 / SYNC 3 APIM Failure — Black Screen, Freezing, and Reboot Loops","solution":"First try a master reset and, importantly, update the APIM to the latest software level — Ford found many returned APIMs were simply running outdated software and did not actually need replacement (TSB guidance for SYNC 3 performance concerns). If the module is truly failed, replace the APIM; a replacement MUST be programmed (As-Built) to the vehicle's VIN/options via Ford service software or FORScan with an extended license — it is not plug-and-play. 2016 trucks adding CarPlay also need USB hub HC3Z-19A387-F. Software update may be free/low cost; programmed APIM replacement typically $400-$900 depending on nav.","description":"The Accessory Protocol Interface Module (APIM) — the computer behind the SYNC 2 and SYNC 3 touchscreen — is a very common failure on 2013-2020 F-150s. Its internal electronics and onboard flash storage degrade over time, producing a black/unresponsive screen (sometimes with backlight on), constant reboot loops stuck at the Ford logo, frozen touch input, and loss of backup-camera display, navigation, phone, and HVAC controls routed through the screen. It usually starts intermittently and worsens. Because the screen also displays the federally mandated rearview camera, a dead APIM is more than a","estimatedCostLow":0,"estimatedCostHigh":900},{"id":"ford-f-150-water-leak-rear-window-third-brake-light-wet-headliner-carpe","make":"Ford","model":"F-150","years":[1997,2004,2005,2006,2007,2008,2009,2010,2011,2012,2013,2014,2015,2016,2017,2018,2019,2020],"trims":[],"engines":["All engines"],"category":"body","severity":"medium","title":"Water Leak at Rear Window / Third Brake Light — Wet Headliner, Carpet, and Cab-Corner Rust","solution":"Pinpoint the source with a careful water test from the bottom up. If the third brake light is the source, remove it and replace the foam gasket and reseal (a common, inexpensive fix). If the rear window is leaking, the back glass must be reset with fresh butyl tape/urethane, or a cracked slider seal replaced. Dry the headliner and carpet thoroughly and treat any cab-corner rust before it perforates; verify cab drain paths are clear. Typical parts+labor for the gasket/reseal runs roughly $100-$300; bodywork for resulting rust is far more.","description":"F-150s have a long-running problem with rainwater entering the cab from the top rear of the cab. Two sources dominate: the foam/rubber gasket behind the high-mounted third brake light dries out and cracks, and the butyl-tape seal around the fixed rear window (or the slider track) deforms with age. Water runs down inside the cab, soaking the headliner and rear carpet and pooling behind the rear seat. Because the cab cavity drains poorly, trapped water rots the cab corners and lower rear seat area from the inside out. Owners report mildew smell, wet rear floor, foggy windows, and corroded seat-b","estimatedCostLow":100,"estimatedCostHigh":600},{"id":"ford-f150-carrier-bearing-2015","make":"Ford","model":"F-150","years":[2015,2016,2017,2018,2019,2020],"trims":[],"engines":[],"category":"drivetrain","severity":"medium","title":"Driveshaft Carrier Bearing Failure","solution":"Replace the carrier bearing assembly ($150-300 parts). Consider upgrading to a heavy-duty carrier bearing if towing frequently. The job requires dropping the driveshaft and is about 2-3 hours labor. Some owners upgrade to aftermarket carrier bearings with greaseable Zerk fittings for longer life.","description":"The two-piece driveshaft uses a center support (carrier) bearing that can wear out, causing vibration and noise. The rubber support degrades over time, especially in hot climates or with heavy towing. Ford TSB addresses this issue.","estimatedCostLow":300,"estimatedCostHigh":700},{"id":"ford-f-150-evap-canister-purge-valve-stuck-open-hard-start-after-refuel","make":"Ford","model":"F-150","years":[2011,2012,2013,2014,2015,2016,2017,2018,2019,2020],"trims":[],"engines":["3.5L EcoBoost V6","2.7L EcoBoost V6","5.0L Coyote V8","3.3L Ti-VCT V6"],"category":"emissions","severity":"low","title":"EVAP Canister Purge Valve Stuck Open — Hard Start After Refueling, Rough Idle, P0455/P0496","solution":"Verify with a smoke test before replacing parts — roughly 30% of P0455/P0456 codes are a loose or cracked gas cap, so reseat/replace the cap and clear first. If the purge valve fails to hold vacuum when commanded closed (it should seal), it is leaking and must be replaced. Inspect the rubber lines from the canister to the valve and to the intake for cracks/collapse and reseat loose connections per TSB 19-2132. After repair, clear codes and complete a drive cycle to allow the EVAP monitor to re-run. The purge valve sits near the throttle body/intake and is a quick R&R; expect roughly $25-$70 for the part plus labor.","description":"The EVAP canister purge valve (purge solenoid) on F-150s commonly sticks in the open position, allowing raw fuel vapor from the charcoal canister to be pulled into the intake when it shouldn't be. This floods the cylinders with vapor — owners report a vehicle that cranks but won't start (or stumbles badly) immediately after filling the tank, then runs fine once it clears. A stuck-open or leaking purge valve, along with cracked/collapsed lines between the canister, valve, and intake manifold, is the most common trigger for P0496 (EVAP flow during a non-purge condition) and a frequent cause of P","estimatedCostLow":60,"estimatedCostHigh":320},{"id":"ford-f-150-sync-4-12-inch-touchscreen-goes-black-freezes-reboots-startu","make":"Ford","model":"F-150","years":[2021,2022,2023,2024],"trims":[],"engines":["All engines (trucks equipped with the 12-inch SYNC 4 screen)"],"category":"electrical","severity":"low","title":"SYNC 4 12-inch Touchscreen Goes Black, Freezes, or Reboots on Startup","solution":"Perform a hard reset by pressing and holding the power and right-seek buttons for about 10 seconds until the screen reboots. Keep SYNC software current but be aware some OTA builds introduced the regression — check Ford's update notes and, if a recent update triggered it, ask the dealer about the latest stable build or a master reset. If resets stop working or the screen stays dead, the dealer can reflash or, in persistent cases, replace the APIM/display module. Allow extra time after large updates, during which the screen can be unresponsive for 2-15 minutes by design.","description":"14th-gen F-150s with the 12-inch SYNC 4 infotainment display commonly suffer a black/blank or frozen screen at startup — sometimes with no Ford logo, sometimes stuck on the splash screen, and sometimes unresponsive for several minutes. Owners report it occurring intermittently (some 2023 trucks roughly 10% of startups) and note it worsened after certain over-the-air updates (e.g., the 4.2.2 and 6.8 OTA builds). With the center screen down, the backup camera, climate controls, radio, and drive-mode selection are unavailable, which is a real usability and visibility concern. A two-button hard re","estimatedCostLow":0,"estimatedCostHigh":1200},{"id":"ford-f-150-door-ajar-switch-sticks-dome-lights-stay-battery-drain","make":"Ford","model":"F-150","years":[1997,1998,1999,2000,2001,2002,2003,2004,2005,2006,2007,2008,2009,2010,2011,2012,2013,2014],"trims":[],"engines":["4.2L V6","4.6L V8","5.4L Triton V8","3.5L EcoBoost V6","5.0L Ti-VCT V8"],"category":"electrical","severity":"low","title":"Door Ajar Switch Sticks — Dome Lights Stay On and Battery Drain","solution":"Isolate which door by watching the message center as you cycle each latch. Spray the latch/switch with a penetrant or electrical/brake cleaner and cycle the door 10-20 times to free the contacts — this fixes most cases. If it recurs, replace the door-ajar/jamb switch or the door latch assembly. Verify the interior lights and drain are gone with a parasitic draw test.","description":"The door-ajar switch built into the door latch sticks or corrodes so the truck thinks a door is open. The result is a 'door ajar' warning that stays on, interior/dome lights that won't shut off, chimes, and a parasitic battery drain that can leave the truck dead overnight. It is one of the most common and widely searched F-150 electrical annoyances across many model years, and is usually a very cheap fix.","estimatedCostLow":40,"estimatedCostHigh":200},{"id":"ford-f-150-driver-s-door-master-power-window-switch-failure","make":"Ford","model":"F-150","years":[2009,2010,2011,2012,2013,2014],"trims":[],"engines":["All (electrical, engine-independent)"],"category":"electrical","severity":"low","title":"Driver's Door Master Power Window Switch Failure","solution":"Test for power and ground at the switch and inspect the connector for corrosion/moisture before condemning it. The usual fix is to replace the driver's master window switch assembly (cleaning carbon-fouled contacts is a temporary fix at best). Check the relevant fuse first. OEM part numbers: 9L3Z-14529-AD / 9L3Z-14529-AE (2009-2010) and BL3T-14540-AAW for 2011-2014. Aftermarket switches are inexpensive. Switch $25-$90; about a 30-60 minute DIY, or ~$100-$200 at a shop.","description":"The driver's door master switch on 2009-2014 F-150s commonly fails electrically (distinct from the mechanical window-regulator/cable failure). Carbon builds up on the internal contacts from current arcing, and the switch's exposed door-panel location lets moisture in when the window is lowered in rain — both degrade the contacts. Because the master switch and the front passenger switch share wiring splices, a failing master can leave one or both front windows dead (or stuck moving), while the rear or passenger-door switches still work. Owners also report a window stuck in one position because ","estimatedCostLow":25,"estimatedCostHigh":200},{"id":"ford-f-150-power-tailgate-lock-actuator-failure-tailgate-opens-by-itsel","make":"Ford","model":"F-150","years":[2015,2016,2017,2018,2019,2020,2021,2022,2023],"trims":[],"engines":["All (body, engine-independent)"],"category":"body","severity":"low","title":"Power Tailgate Lock Actuator Failure / Tailgate Opens by Itself","solution":"For no-open/intermittent operation, replace the tailgate lock actuator motor — OEM GC3Z-9943170-E (also cross-referenced FL3Z-9943170-C / GC3Z-9943170-A/B) for 2015-2023 power-tailgate trucks; the manual handle remains as a backup. For self-opening/unlocking, clean and dielectric-grease the corroded connector near the spare tire (inspect every ~6 months in salt regions) and repair any chafed wiring; verify BCM isn't seeing a false signal. Actuator ~$60-$180; DIY replacement ~30-45 min, or $150-$250 at a dealer.","description":"On 2015+ aluminum-body F-150s with the power-locking/keyless tailgate, the electric tailgate lock actuator weakens and fails — it clicks but won't lock/unlock, operates intermittently (especially in cold weather), grinds, or quits entirely so the tailgate won't open from the key fob or handle. A second, well-documented failure mode is the tailgate releasing or unlocking on its own: a connector near the spare tire lets in snow, ice, and road salt, corroding the circuit and sending a false release signal to the BCM, which can open/unlock the tailgate unexpectedly (a security and cargo-loss conce","estimatedCostLow":60,"estimatedCostHigh":250},{"id":"ford-f150-blend-door-2015","make":"Ford","model":"F-150","years":[2015,2016,2017,2018,2019,2020,2021,2022,2023],"trims":[],"engines":[],"category":"electrical","severity":"low","title":"HVAC Blend Door Actuator Failure","solution":"Replace failed blend door actuator. Actuators are located behind dashboard and require some disassembly. Consider replacing multiple actuators if one fails as others may follow. OEM parts recommended.","description":"The HVAC blend door actuators can fail, causing clicking noises from the dashboard and inability to control air temperature. Air may blow only hot or only cold regardless of settings. Multiple actuators are used and any can fail.","estimatedCostLow":100,"estimatedCostHigh":500},{"id":"ford-f-150-c-evaporator-core-leak-weak-warm-c-musty-smell","make":"Ford","model":"F-150","years":[2012,2013,2014,2015,2016,2017,2018,2019,2020],"trims":[],"engines":["3.5L EcoBoost V6","2.7L EcoBoost V6","5.0L Ti-VCT V8","5.4L Triton V8"],"category":"hvac","severity":"low","title":"A/C Evaporator Core Leak — Weak/Warm A/C and Musty Smell","solution":"Confirm the leak with dye or an electronic sniffer / nitrogen pressure test after verifying it isn't a condenser, line, or O-ring leak (cheaper to fix). Evaporator replacement requires dash/HVAC-box removal, evacuation, new O-rings and desiccant/accumulator, and a proper recharge to spec. Replace the cabin filter and treat the case to address the musty smell.","description":"The evaporator core inside the dash develops small refrigerant leaks that slowly bleed the system down, leaving the A/C blowing warm or only cold intermittently; a musty odor is a common companion complaint. Because the evaporator is buried behind the dash, the leak is easy to miss and repeat 'recharge' visits don't hold. CarComplaints documents evaporator-leak complaints across several model years, and it is one of the more labor-intensive HVAC repairs on the truck.","estimatedCostLow":1000,"estimatedCostHigh":1900},{"id":"jeep-grand-cherokee-air-suspension-2011","make":"Jeep","model":"Grand Cherokee","years":[2011,2012,2013,2014,2015,2016,2017,2018,2019,2020,2021],"trims":[],"engines":[],"category":"suspension","severity":"medium","title":"2011-2021 Quadra-Lift Warning or Uneven Ride Height - Diagnose Before Parts","solution":"Confirm the vehicle is equipped with Quadra-Lift sales code SER, record the exact ASCM DTCs and environmental data, and check VIN/build-date-specific FCA bulletins before ordering hardware. Follow the factory sequence: repair voltage or communication faults first; inspect fuses, air lines, springs, height-sensor linkages, compressor intake/filter, and visible plumbing; then use a capable scan tool to run the Air Mass and Air Ride Height routines and follow the DTC-specific tree. On 2011-2012 vehicles built before May 1, 2012, U0415-00 or C159E-15 with a Service Air Suspension message may be addressed by FCA TSB 08-034-12's ASCM software update. Replace only the component proven failed. A completely depleted system requires the specified refill equipment, scan-tool procedure, and purity-class-5 nitrogen; do not fill it with ordinary shop air or shotgun-replace springs, sensors, and the compressor.","description":"Quadra-Lift is a closed, electronically controlled air-suspension system, so a Service Air Suspension message, a low corner, or a denied height change does not identify one universal failed part. The factory diagnostic path covers electrical and communication faults, fuses and voltage, pinched or damaged lines, leaking springs, disconnected sensor linkages, water or blockage in the compressor intake, air-mass loss, valve/compressor faults, software, and the Air Suspension Control Module. The prior card also incorrectly treated SRT and Trackhawk as automatic Quadra-Lift applications; applicabil","estimatedCostLow":null,"estimatedCostHigh":null},{"id":"jeep-grand-cherokee-front-wheel-speed-sensor-failure-triggering-abs-esp-bas-trac","make":"Jeep","model":"Grand Cherokee","years":[2019],"trims":[],"engines":[],"category":"brakes","severity":"medium","title":"2019 Grand Cherokee ABS Warning - Diagnose the Wheel-Speed Circuit First","solution":"Read the ABS module and compare individual wheel-speed live data to isolate the affected circuit. Inspect the connector latch, pins, and harness for water intrusion, corrosion, routing problems, or damage; replace a damaged harness rather than the sensor. Inspect and clean the sensor mounting area and tone wheel, reinstall the sensor, and retest the signal. Replace the sensor only when electrical and signal testing confirms it is faulty, then clear faults and verify normal wheel-speed data on a road test. Confirm any replacement by VIN and installed equipment before ordering.","description":"On 2019 model-year Jeep Grand Cherokee (WK) vehicles, an ABS warning that diagnosis traces to a wheel-speed circuit may be caused by an incompletely latched connector, water intrusion and corroded connector pins, rust or contamination at the sensor and tone wheel, or a faulty sensor. FCA warns that replacing a good sensor while leaving a damaged harness in place can cause the concern to return. The previous card incorrectly generalized this condition across 2011-2021 vehicles, named the right-front sensor as a common cause, listed unsupported DTCs and symptoms, and presented three universal re","estimatedCostLow":null,"estimatedCostHigh":null},{"id":"jeep-grand-cherokee-body-control-module-electrical-faults-causing-uconnect-reboo","make":"Jeep","model":"Grand Cherokee","years":[2014,2015,2016,2017,2018],"trims":[],"engines":[],"category":"electrical","severity":"medium","title":"2014-2018 Uconnect Reboots, Accessory Faults or Battery Drain - Separate the Causes","solution":"Start with a complete vehicle scan and save active, stored, and environmental data before clearing anything. Load-test the battery, verify charging voltage, and repair low-voltage faults first. Inspect the relevant fuses, power feeds, grounds, connectors, and CAN wiring, then measure key-off draw only after the vehicle has completed its normal sleep period and isolate the circuit that remains awake. For radio resets, identify the exact radio sales code and vehicle build date and check the VIN for the applicable FCA software or radio procedure. For a lost-communication fault, determine whether the named module is actually offline, whether multiple modules logged against it, and whether its power, ground, and network circuits pass before condemning it. Replace and VIN-configure a BCM, radio, IBS, or battery only when the component-specific test proves it failed.","description":"Uconnect resets or a blank screen, intermittent accessories, a discharged battery, and communication faults may occur together, but they do not establish that the Body Control Module is defective. Radio software or hardware, a weak battery or charging problem, poor power or ground, damaged CAN wiring or terminals, another module that will not sleep, and a true internal module fault can overlap. FCA has a software bulletin for specific early 2014 WK vehicles with RA3/RA4 radios, including radio resets and radio-caused battery drain, but that bulletin is sales-code and build-date specific and do","estimatedCostLow":null,"estimatedCostHigh":null},{"id":"jeep-grand-cherokee-center-high-mount-stop-lamp-liftgate-wiring-grommet-water-le","make":"Jeep","model":"Grand Cherokee","years":[2011,2012,2013,2014,2015,2016,2017,2018,2019,2020,2021],"trims":[],"engines":[],"category":"body","severity":"low","title":"2011-2021 WK2 Rear Cargo Water Intrusion - Locate the Entry Path First","solution":"Dry the accessible area enough to see a new water track, protect affected electrical connectors and modules, and reproduce the conditions under which the leak occurs. Follow the factory water-leak procedure: visually inspect plugs, drains, alignment, seams, seals, and grommets; test one region at a time with an appropriate low-pressure stream or fan spray; remove trim only as needed for safe visual access; and trace the highest fresh water track to its actual entry point. Repair, reseat, or replace only the confirmed failed seal, seam, fastener, drain, weatherstrip, glass bond, lamp seal, or wiring pass-through using the current factory procedure and specified material. Dry wet insulation, inspect exposed terminals for corrosion, and repeat the water test before closing the trim. Do not smear generic RTV across several unconfirmed paths.","description":"Water found in a WK2 Grand Cherokee cargo well, under the cargo floor, or near a rear pillar is a symptom, not proof that one grommet, weatherstrip, lamp gasket, antenna seal, or roof seam has failed. The factory water-leak procedure warns that water can travel through body cavities and appear far from the true entry point. The old card's shopping list could therefore send an owner to four unrelated products before the leak location was established.","estimatedCostLow":null,"estimatedCostHigh":null},{"id":"chevrolet-silverado-1500-10l80-10l90-10-speed-valve-body-failure-no-reverse-service-t","make":"Chevrolet","model":"Silverado 1500","years":[2024,2025],"trims":[],"engines":["5.3L V8 L84","6.2L V8 L87","3.0L Duramax LZ0 I6"],"category":"transmission","severity":"high","title":"10L80/10L90 10-Speed Valve Body Failure — No Reverse, 'Service Transmission', and National Parts Backorder","solution":"GM issued TSB #25-NA-255 (Sept 22, 2025) instructing technicians to repair rather than replace the valve body on 2021-2024 Silverado/Sierra 1500 and full-size SUVs with the 10L80/10L90 when P0747 is stored. The repair installs a redesigned steel Feed Limit Low Valve, a higher-tension Feed Limit Valve Spring, and a new valve body spacer plate and gasket, torqued to 80 in-lb; it requires a minimum of 7,000 miles and must not be performed if the pan shows significant clutch debris. Ask for this kit by bulletin number instead of accepting an open-ended backorder on a complete valve body. Covered under the 5yr/60,000-mile powertrain warranty for these model years. If clutch material is present in the pan, the correct repair is a transmission replacement, not the valve body kit.","description":"2024-2025 Silverado 1500 trucks with the 10-speed automatic (5.3L L84, 6.2L L87, 3.0L Duramax LZ0) are suffering stuck valve-body solenoids at very low mileage. Owners report a 'Service Transmission' or 'Service Transmission — Unable to Shift' message, violent hard downshifts, slipping, and complete loss of reverse — several describe rolling backwards down a slope or having to push the truck out of a parking space. The failure typically drops the truck into a default limp mode. NHTSA reports cite P0747 and P0700, and one owner had the valve body replaced only for the fault to return. The parts","estimatedCostLow":900,"estimatedCostHigh":6500},{"id":"chevrolet-silverado-1500-3-0l-duramax-service-emission-system-limp-mode-from-def-nox","make":"Chevrolet","model":"Silverado 1500","years":[2020,2021,2022,2023,2024],"trims":[],"engines":["3.0L LM2 Duramax","3.0L LZ0 Duramax"],"category":"emissions","severity":"high","title":"3.0L Duramax 'Service Emission System' Limp-Mode From DEF/NOx Sensor Faults","solution":"Scan for the specific reductant/NOx code before parts. Apply the latest GM ECM/emissions software update (dealer TSB) for false MIL/DEF-level triggers; replace the failed DEF level/quality sensor, NOx sensor, or reductant injector as indicated. Use only fresh, spec DEF and confirm the countdown resets after repair. Many repairs fall under emissions/powertrain warranty.","description":"The 3.0L Duramax throws a 'Service Emission System' warning with a staged speed-limit countdown (e.g. 'In 175 miles speed will be limited to 65 mph', then 55 mph, then a no-restart threshold), frequently dropping the truck into limp mode. Root causes are faulty DEF level/quality sensors, NOx sensors, or a bad DEF injector/reductant heater, often triggered even when DEF is topped off. GM addressed several false-trigger cases with a software update (TSB 21-NA-071 family) but sensor hardware failures remain common and leave owners stranded on countdowns.","estimatedCostLow":200,"estimatedCostHigh":1500},{"id":"chevrolet-silverado-1500-4l60e-automatic-transmission-3-4-clutch-pack-sun-shell-failu","make":"Chevrolet","model":"Silverado 1500","years":[1994,1995,1996,1997,1998,1999,2000,2001,2002,2003,2004,2005,2006,2007,2008,2009,2010],"trims":[],"engines":["4.3L V6 Vortec","4.8L V8 Vortec","5.3L V8 Vortec","5.7L V8 Vortec","6.0L V8 Vortec"],"category":"transmission","severity":"high","title":"4L60E Automatic Transmission 3-4 Clutch Pack and Sun Shell Failure (Slipping, Loss of 3rd/4th Gear)","solution":"Confirm with a scan for gear-ratio/slip codes and a pressure test before condemning the unit. Fix is a transmission rebuild or reman: replace the 3-4 clutch pack, install a hardened 4L60E sun shell (aftermarket beast/heavy-duty shell over the stamped OEM piece), fresh bands/steels, and rebuild or replace the valve body. Adding an auxiliary transmission cooler and shortening fluid-change intervals to ~30k miles greatly extends life. Reman units are widely available; a full-service rebuild with upgraded shell is the durable fix.","description":"The 4L60E 4-speed automatic behind the half-ton Silverado is notorious for wearing out its 3-4 clutch pack and cracking the input 'sun shell' (reaction sun gear shell) as mileage climbs. Owners report the truck suddenly loses 3rd and 4th gear (revs up but won't pull) while reverse and low gears still work, or a hard grinding/no-move with a fractured sun shell. The 3-4 clutch is the known weak point and often burns up first; the larger input drum on 2004-and-up units also likes to crack internally. This is one of the single most-searched failures for these trucks.","estimatedCostLow":1500,"estimatedCostHigh":2800},{"id":"chevrolet-silverado-1500-5-3l-vortec-5300-excessive-oil-consumption-from-piston-rings","make":"Chevrolet","model":"Silverado 1500","years":[2010,2011,2012,2013,2014],"trims":["LS","LT","LTZ"],"engines":["5.3L V8 LC9","5.3L V8 LMG","5.3L V8 Vortec 5300"],"category":"engine","severity":"high","title":"5.3L Vortec 5300 (Gen IV LC9/LMG) Excessive Oil Consumption from Piston Rings/AFM","solution":"GM's progression of TSBs added an AFM oil-deflector/shield and revised PCV provisions and ultimately upgraded the piston rings under warranty. Verified fix is replacement of the pistons/rings (and AFM oil-pressure relief valve / valley-cover shield); many owners opt for an AFM delete with a non-AFM cam, lifters, and tune to permanently resolve it. Monitor and top off oil between changes; replace oil-fouled spark plugs. Settlement payments (~$3,380) were available to eligible owners in CA, ID, and NC who had not already received free warranty piston repairs.","description":"Generation IV 5.3L Vortec engines burn an abnormal amount of oil — many owners report a quart or more every 1,000-2,000 miles. The defect is a combination of low-tension piston rings that fail to control oil, oil spray from the Active Fuel Management (AFM) system during cylinder deactivation, and a PCV path that draws oil mist into the intake. The oil fouls and prematurely wears spark plugs, causing rough idle, misfires, and a check-engine light. This was the subject of the Siqueiros v. GM class action (N.D. Cal., No. 3:16-cv-07244), which reached a final settlement in October 2025.","estimatedCostLow":1500,"estimatedCostHigh":4500},{"id":"chevrolet-silverado-1500-8-speed-torque-converter-clutch-shudder-harsh-shifting","make":"Chevrolet","model":"Silverado 1500","years":[2015,2016,2017,2018,2019],"trims":[],"engines":["5.3L V8 L83","6.2L V8 L86"],"category":"transmission","severity":"high","title":"8-speed (8L90/8L45) torque converter clutch shudder and harsh shifting","solution":"Per GM's bulletins, the first step is a complete transmission fluid flush-and-fill with the updated low-shudder fluid (Mobil 1 Synthetic LV ATF HP / Dexron HP), which resolves many cases. Persistent shudder or hard shifts after the flush typically require torque converter replacement, and in severe cases (metal contamination) a valve body or transmission overhaul. Some owners use aftermarket friction-modifier additives as a stopgap.","description":"Silverados equipped with the GM 8L90 (and the lighter 8L45) eight-speed automatic suffer a widespread torque-converter-clutch (TCC) shudder, often described as driving over a rumble strip during light cruising, plus harsh/clunky 1-2 and 2-1 shifts and slipping. GM traced it largely to the torque converter and to the original transmission fluid degrading and creating friction, which can shed metal debris into the unit. The defect is documented in GM TSBs 18-NA-355 and 19-NA-219 and was the basis of a consolidated class-action lawsuit alleging the 8L90/8L45 are defective. Early-build 2015-2017 t","estimatedCostLow":300,"estimatedCostHigh":3500},{"id":"chevrolet-silverado-1500-brake-fuel-line-corrosion-failure","make":"Chevrolet","model":"Silverado 1500","years":[2007,2008,2009,2010,2011,2012,2013,2014],"trims":["LS","LT","LTZ","Work Truck"],"engines":["4.3L V6","4.8L V8","5.3L V8","6.0L V8"],"category":"brakes","severity":"high","title":"Brake / Fuel Line Corrosion Failure (Galvanized Steel Lines, Salt-Belt)","solution":"Inspect all underbody brake and fuel lines for surface rust/flaking, especially over the rear axle and along the frame rails. Replace corroded sections with GM's pre-formed brake-line kit (TSB 13-05-22-001) or aftermarket coated/stainless lines; bleed the system afterward. Proactively replace lines as a set in salt-belt trucks before failure, and wash the underbody regularly through winter. Any soft/sinking pedal or visible fluid leak should be treated as do-not-drive.","description":"The original galvanized-steel brake (and fuel) lines on these trucks lack the modern nylon/PVF anti-corrosion coating, so in cold-weather/road-salt states the lines rust from the outside in and rupture. A brake-line burst causes sudden, often warning-light-free loss of brake pressure and a long/soft pedal; NHTSA logged hundreds of complaints and opened (then closed without recall) an investigation into salt-belt GM trucks. GM addressed it with a TSB and a pre-formed replacement-line kit rather than a recall.","estimatedCostLow":300,"estimatedCostHigh":1200},{"id":"chevrolet-silverado-1500-csfi-cpi-spider-fuel-injector-assembly-failure","make":"Chevrolet","model":"Silverado 1500","years":[1996,1997,1998,1999,2000,2001,2002],"trims":[],"engines":["4.3L V6 Vortec","5.0L V8 Vortec","5.7L V8 Vortec"],"category":"fuel","severity":"high","title":"CSFI/CPI 'Spider' Fuel Injector Assembly Failure (Misfire, Rough Idle, Poor Fuel Economy)","solution":"Test fuel pressure and look for a leak-down after key-off; inspect the spider for wet fuel/leaking poppets. The durable repair is to replace the entire spider assembly, ideally upgrading the early poppet-style CSFI unit to the later MPFI-style spider (a GM-engineered redesign that bolts in on 1996-2001 engines with no modification). Reman upgraded assemblies with new regulator and Viton O-rings are widely sold; verify the exact GM/ACDelco part for your specific engine before buying rather than guessing.","description":"The Central Sequential/Port Fuel Injection ('spider') assembly used on Vortec 4.3L/5.0L/5.7L engines feeds nylon lines to poppet or MPFI nozzles inside the intake. Over time the poppet valves gum up and stick, O-rings and the pressure regulator leak, and the nylon lines crack. The result is misfires, hard starting, rough idle, a noticeable drop in fuel economy, and often a raw-fuel/rich condition. A leaking regulator can even flood a cylinder (hydrolock risk). Very high-demand failure on these older trucks.","estimatedCostLow":300,"estimatedCostHigh":900},{"id":"chevrolet-silverado-1500-transmission-overheating-from-failed-8l90-thermal-bypass-val","make":"Chevrolet","model":"Silverado 1500","years":[2015,2016,2017,2018,2019,2020,2021,2022],"trims":[],"engines":["5.3L V8","6.2L V8"],"category":"transmission","severity":"medium","title":"Transmission Overheating from Failed 8L90 Thermal Bypass Valve / Cooler-Line Leaks","solution":"Verify transmission temperature behavior and inspect the cooler lines/fittings for leaks. Replace or delete/upgrade the failed thermal bypass valve so fluid reaches the cooler, repair leaking cooler lines/fittings, and service with fresh Dexron-VI fluid. Adding or upgrading an external transmission cooler is a common preventive measure for trucks that tow. Confirm fluid level and condition, as low/oxidized fluid both causes and results from overheating.","description":"Silverado 1500 trucks with the 8L90 eight-speed (and the older 6L80 six-speed) can run dangerously hot when the factory transmission thermal bypass valve sticks closed, so fluid never reaches the cooler — common under towing or heavy load. Sustained temperatures above ~220-250°F oxidize the fluid and cook the clutches and torque converter, accelerating the separately-known shudder/wear and shortening transmission life. Compounding this, the transmission cooler lines and fittings are a frequent leak point on these trucks, dropping fluid level and worsening heat. Owners towing in hot climates ar","estimatedCostLow":150,"estimatedCostHigh":1200},{"id":"chevrolet-silverado-1500-2-7l-turbomax-cold-start-rattle-wastegate-actuator-wear","make":"Chevrolet","model":"Silverado 1500","years":[2019,2020,2021,2022,2023,2024],"trims":["Work Truck","Custom","LT","RST"],"engines":["2.7L Turbo L3B"],"category":"engine","severity":"medium","title":"2.7L Turbomax (L3B) Cold-Start Rattle and Wastegate Actuator Wear","solution":"GM TSB 23-NA-058 addresses the cold-start rattle with a worn wastegate linkage — the fix is replacement of the wastegate actuator or, when the linkage is worn through, the complete turbocharger assembly. For the P0011/P0014 camshaft-timing codes, replace the failed camshaft position actuator magnet (solenoid) per PIP5855 and re-torque the loose intake-cam actuator cover-plate screws per PIP5921B. Walnut-blast the intake valves to clear carbon on higher-mileage engines.","description":"The turbocharged 2.7L Turbomax four-cylinder develops a metallic rattle/knock on cold start-up, most pronounced in the first few seconds before oil pressure builds. The root cause is premature wear in the turbocharger wastegate linkage/actuator, which can also throw a turbo-underboost code. Owners also report VVT camshaft-actuator (CPAS) solenoid faults and engine-harness chafing on this engine. Because the L3B is direct-injection only (no port injection), intake-valve carbon buildup compounds the rough-idle/misfire complaints as miles accumulate.","estimatedCostLow":300,"estimatedCostHigh":2500},{"id":"chevrolet-silverado-1500-c-condenser-cracking-leaking-causing-loss-cooling","make":"Chevrolet","model":"Silverado 1500","years":[2014,2015,2016,2017,2018],"trims":[],"engines":[],"category":"hvac","severity":"medium","title":"A/C condenser cracking/leaking causing loss of cooling (blows hot air)","solution":"Confirm the leak (UV dye / electronic sniffer at the condenser welds), then replace the condenser with the revised-design unit, evacuate and recharge the system with the correct R134a charge, and replace the receiver/drier and any contaminated orifice/expansion components. Out-of-warranty owners often use a quality aftermarket condenser to control cost.","description":"The factory air-conditioning condenser on 2014-2018 Silverado 1500 trucks is prone to cracking and refrigerant leakage, frequently at the spot welds on the sides of the condenser where vibration concentrates stress (revised replacement units add welds to spread the load). The result is a slow R134a leak and the A/C gradually blowing warm/hot air, often with under 50,000-70,000 miles. The problem is heavily documented on CarComplaints (13 condenser-cracked complaints on the 2016, 26 A/C-blowing-hot complaints on the 2015) and led to a GM A/C class-action that survived dismissal. Owners report p","estimatedCostLow":600,"estimatedCostHigh":1100},{"id":"chevrolet-silverado-1500-water-pump-failure-weep-hole-coolant-leak-5-3l-6-2l-v8","make":"Chevrolet","model":"Silverado 1500","years":[2007,2008,2009,2010,2011,2012,2013,2014,2015,2016,2017,2018,2019,2020,2021,2022,2023,2024],"trims":[],"engines":["4.8L V8","5.3L V8","6.0L V8","6.2L V8"],"category":"cooling","severity":"medium","title":"Water Pump Failure / Weep-Hole Coolant Leak on 5.3L and 6.2L V8","solution":"Pressure-test the cooling system and confirm the leak is from the pump weep hole / shaft seal versus a gasket or hose. Replace the water pump (and gasket), refill with the correct GM Dex-Cool spec coolant, and bleed the system. Inspect the belt and tensioner while accessing the pump. Address any low-coolant overheating before it damages head gaskets.","description":"The mechanical (belt-driven) water pump on the LS/LT V8 Silverado 1500 is a common wear-out item. The internal shaft seal fails and coolant seeps from the pump's weep hole, often appearing as orange/Dex-Cool residue or a puddle at the front-center of the truck; the weep-hole drip can be hard to spot until the bearing also starts to whine. Owners report leaks commonly at roughly 60,000-100,000 miles. If ignored it leads to coolant loss and overheating. Some apparent water-pump leaks turn out to be a failed gasket rather than the pump itself, so confirmation matters.","estimatedCostLow":200,"estimatedCostHigh":1450},{"id":"chevrolet-silverado-1500-service-stabilitrak-service-traction-control-reduced-engine","make":"Chevrolet","model":"Silverado 1500","years":[2014,2015,2016,2017,2018,2019,2020,2021,2022],"trims":[],"engines":["4.3L V6","5.3L V8","6.2L V8"],"category":"electrical","severity":"medium","title":"Service StabiliTrak / Service Traction Control / 'Reduced Engine Power' Cascade","solution":"Scan for stored codes (commonly P2138 and related APP/throttle codes) and read live throttle/pedal data. Start by inspecting and cleaning the body grounds under the driver's door and the main harness connector (a known fix), then test/replace the APP sensor or throttle body as indicated. Apply any GM throttle-body or PCM software updates. Confirm the actual failed component before replacing the throttle body, as wiring/ground faults mimic sensor failure.","description":"A widely reported Silverado 1500 complaint is a sudden cascade of dash messages — 'StabiliTrak disabled,' then 'Service StabiliTrak,' 'Service Traction Control,' and finally 'Engine Power Reduced' — sometimes with a stumble or stall and limited throttle response. The most common root causes are a faulty accelerator pedal position (APP) sensor or throttle body (electronic throttle), but it is also frequently traced to poor/corroded ground connections and chafed wiring under the driver's door sill or at the underseat/main harness connector. Because it can drop the truck into reduced-power limp m","estimatedCostLow":150,"estimatedCostHigh":700},{"id":"chevy-silverado-ac-compressor-2014","make":"Chevrolet","model":"Silverado 1500","years":[2014,2015,2016,2017,2018,2019,2020],"trims":[],"engines":[],"category":"electrical","severity":"medium","title":"A/C Compressor Failure","solution":"Replace A/C compressor assembly. If internal failure, flush entire system, replace condenser, receiver/drier, and expansion valve. Use quality replacement parts. Verify proper oil charge in new compressor.","description":"The A/C compressor can fail prematurely, especially on trucks in hot climates or with heavy A/C use. Internal compressor failure can contaminate the entire A/C system with debris, requiring extensive repairs.","estimatedCostLow":600,"estimatedCostHigh":1800},{"id":"chevrolet-silverado-1500-passlock-anti-theft-crank-no-start","make":"Chevrolet","model":"Silverado 1500","years":[1999,2000,2001,2002,2003,2004,2005,2006,2007],"trims":[],"engines":["4.3L V6 Vortec","4.8L V8 Vortec","5.3L V8 Vortec","6.0L V8 Vortec"],"category":"electrical","severity":"medium","title":"Passlock Anti-Theft Crank-No-Start ('Service Theft System' / Flashing Security Light)","solution":"First try the 10-minute relearn: key to ON, attempt start, then leave key ON until the security light stops flashing (~10 min), key off 5 sec, then start; repeat up to 3 cycles. If it recurs, replace the Passlock sensor or ignition lock cylinder and relearn. A common permanent workaround is a resistor bypass of the Passlock sense circuit. Scan for B2960/B3031/B3033 to confirm before parts.","description":"The Passlock II theft-deterrent system reads a Hall-effect sensor and magnet in the ignition lock cylinder. As the sensor or lock cylinder wears, the BCM sees an out-of-range voltage, flags a theft fault, flashes the SECURITY light, and disables fuel injection so the engine cranks but won't start. Owners get stranded with a 'Service Theft System' or security light and a no-start that often clears after a wait. Extremely common and heavily searched on these trucks.","estimatedCostLow":10,"estimatedCostHigh":350}]

